message.content:
{
  "css": ".itinerary {
  color: #111;
}

.day-group h2 {
  font-size: 16px;
  line-height: 22px;
  font-weight: 700;
  margin-bottom: 16px;
}

.day-group > section {
  margin-top: 18px;
}

.day-group + .day-group {
  margin-top: 40px;
}

.place-row {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 9px;
  align-items: center;
}

.place-card {
  display: flex;
  align-items: stretch;
  min-width: 0;
  min-height: 96px;
  height: auto;
  border: 1px solid #e8e8e8;
  border-radius: 6px;
  overflow: hidden;
}

.place-photo {
  width: 96px;
  height: 96px;
  flex: 0 0 96px;
  object-fit: cover;
}

.place-copy {
  min-width: 0;
  flex: 1;
  padding: 8px 12px;
  overflow-wrap: anywhere;
}

.place-title {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 700;
  margin-bottom: 4px;
}

.place-type,
.place-region {
  display: block;
  font-size: 14px;
  line-height: 19px;
  font-weight: 500;
  color: #666;
  margin-bottom: 2px;
}

.place-grip {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  margin-right: 6px;
  align-self: center;
}

.partial-slot {
  margin-left: 31px;
  height: 18px;
  overflow: hidden;
}

.partial-card {
  min-height: 96px;
  border: 1px solid #e8e8e8;
  border-radius: 6px 0 0 0;
  display: flex;
  align-items: center;
}

.partial-card img {
  width: 96px;
  height: auto;
  object-fit: cover;
}

@media (max-width: 360px) {
  .place-photo {
    width: 72px;
    height: 72px;
    flex-basis: 72px;
  }

  .place-copy {
    padding: 8px;
  }

  .partial-card img {
    width: 72px;
  }
}"
}
